#ifndef _PHLOP_TIMING_PERF_COUNTERS_HPP_
#define _PHLOP_TIMING_PERF_COUNTERS_HPP_

// Hardware counters for PHLOP_SCOPE(key, perf_light / perf_all), linux only:
// elsewhere perf scopes only time, init() says so once if PHLOP_PERF_* is set.
//
// Events come from the environment, generated by the python event sets:
//   eval "$(python3 -m phlop.app.pfm.stat --env perf_light=light --env perf_all=topdown)"
// which exports eg
//   PHLOP_PERF_LIGHT="amd64_fam1ah_zen5/light;cycles=0x76,instructions=0xc0,..."
// format: "<label>;<name>=<config>,...", config is perf_event_attr type RAW, or
// "hw:<id>" for type HARDWARE: perf generic events, used on CPUs without phlop
// event sets, label "generic/<set>". A "k:" prefix, eg "k:0xc0" or "k:hw:1",
// counts kernel space too, from --env ... --kernel, label "<pmu>/<set>+kernel":
// needs perf_event_paranoid <= 1 or CAP_PERFMON. Kernel counts include the
// kernel side of the scope's own counter read() calls, ~2k instructions per
// scope on zen5: noise for I/O scopes, not for tiny ones. Counts are then potentially inaccurate,
// init() says so, as it does for PHLOP_PERF_CTX "pmu_forced=1": events encoded
// for a libpfm PMU forced via LIBPFM_FORCE_PMU, not this CPU's.
//
// Config: process wide, the union of both levels' events, set by init().
// Group: per thread, perf_event_open counts only the calling thread, so each
// thread opens its own pinned group on its first counted scope. A scope reads
// the whole group with one read() and keeps its level's values. Pinned means
// exact counts or a loud failure, never silent multiplexing. User space only
// unless "k:", works with perf_event_paranoid=2.

#include <array>
#include <atomic>
#include <string>
#include <vector>
#include <cerrno>
#include <cctype>
#include <cstdio>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <string_view>

#if defined(__linux__)
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/syscall.h>
#include <linux/perf_event.h>
#endif

namespace phlop::perf
{

inline constexpr std::size_t max_events = 8; // more than any PMU schedules at once
using Counts = std::array<std::uint64_t, max_events>;

// level 1: perf_light, level 2: perf_all, as written to the timer file
inline constexpr std::array<char const*, 3> level_env{"", "PHLOP_PERF_LIGHT", "PHLOP_PERF_ALL"};
// measuring host values the metric formulas need, eg "slots=5,sve_bits=128",
// written to the timer file as "#ctx ..." so readers on other hosts use them
inline constexpr char const* ctx_env = "PHLOP_PERF_CTX";

// perf_event_attr.type values, stable kernel ABI, defined here for non linux
inline constexpr std::uint32_t type_hardware = 0, type_raw = 4;
#if defined(__linux__)
static_assert(type_hardware == PERF_TYPE_HARDWARE and type_raw == PERF_TYPE_RAW);
#endif

struct Event
{
    std::uint32_t type = type_raw;
    std::uint64_t config = 0;
    bool kernel          = false; // "k:", user and kernel space

    bool operator==(Event const&) const = default;
};

struct Level
{
    std::string label;              // eg "amd64_fam1ah_zen5/light"
    std::vector<std::string> names; // per event
    std::vector<std::size_t> idx;   // per event, into the group
};


struct Config
{
    // defined in src/phlop/timing/{scope_timer,common_threaded_timer}.cpp, not inline:
    // one instance per process even across shared libraries built with -fvisibility=hidden
    static Config& INSTANCE();

    // parse the env and open the calling thread's group to check it works.
    // Without any env this is a no-op, perf scopes then only time
    bool init();

    void close()
    {
        ctx.clear();
        pmu_forced = false;
        configs.clear();
        for (auto& l : levels)
            l = Level{};
        ok = false;
        ++generation; // every thread's group reopens, or closes, on next use
    }

    bool has(std::size_t const level) const
    {
        return ok && level < levels.size() && !levels[level].idx.empty();
    }

    // "#perf <level> <label> <name,...>" lines for the timer file header,
    // and "#ctx <key=value,...>" from PHLOP_PERF_CTX
    std::vector<std::string> file_headers() const
    {
        std::vector<std::string> lines;
        if (ok and !ctx.empty())
            lines.emplace_back("#ctx " + ctx);
        for (std::size_t l = 1; l < levels.size(); ++l)
            if (has(l))
            {
                std::string line = "#perf " + std::to_string(l) + " " + levels[l].label + " ";
                for (std::size_t i = 0; i < levels[l].names.size(); ++i)
                    line += (i ? "," : "") + levels[l].names[i];
                lines.emplace_back(std::move(line));
            }
        return lines;
    }

    // generic events, a forced PMU or kernel counting: printed once, after a successful init
    void accuracy_notices();

    // printed once per process, the first thread to fail says why
    void report(std::string const& why)
    {
        if (!reported.exchange(true))
            std::fprintf(stderr, "phlop perf counters: %s\n", why.c_str());
    }

    bool ok = false;
    std::string error;
    std::string ctx; // PHLOP_PERF_CTX, validated "key=integer,..."
    bool pmu_forced = false; // ctx pmu_forced != 0, see accuracy_notices
    std::array<Level, level_env.size()> levels{};
    std::vector<Event> configs; // union of all levels, group order
    std::atomic<std::uint64_t> generation{1};
    std::atomic<std::uint64_t> read_failures{0}, open_failures{0};
    std::atomic<bool> reported{false};

private:
    // "key=integer,...", sets pmu_forced. False, nothing set, if malformed
    bool parse_ctx(std::string_view s)
    {
        bool forced = false;
        while (!s.empty())
        {
            auto const comma = s.find(',');
            auto const item  = s.substr(0, comma);
            auto const eq    = item.find('=');
            if (eq == 0 or eq == std::string_view::npos)
                return false;
            for (char const c : item.substr(0, eq))
                if (!(std::isalnum(static_cast<unsigned char>(c)) or c == '_'))
                    return false;
            std::string const value{item.substr(eq + 1)};
            char* end              = nullptr;
            long long const number = std::strtoll(value.c_str(), &end, 10);
            if (value.empty() or *end)
                return false;
            if (item.substr(0, eq) == "pmu_forced")
                forced = number != 0;
            s.remove_prefix(comma == std::string_view::npos ? s.size() : comma + 1);
        }
        pmu_forced = forced;
        return true;
    }

    bool parse(std::size_t const l, std::string_view s)
    {
        auto const semi = s.find(';');
        if (semi == std::string_view::npos)
            return false;
        auto& level = levels[l];
        level.label = std::string{s.substr(0, semi)};
        s.remove_prefix(semi + 1);
        while (!s.empty())
        {
            auto const comma = s.find(',');
            auto const item  = s.substr(0, comma);
            auto const eq    = item.find('=');
            if (eq == std::string_view::npos)
                return false;
            auto value = item.substr(eq + 1);
            Event event;
            if (value.starts_with("k:"))
            {
                event.kernel = true;
                value.remove_prefix(2);
            }
            if (value.starts_with("hw:"))
            {
                event.type = type_hardware;
                value.remove_prefix(3);
            }
            std::string const number{value};
            char* end    = nullptr;
            event.config = std::strtoull(number.c_str(), &end, 0);
            if (end == number.c_str() or *end)
                return false;

            std::size_t idx = 0; // shared with the other level if the same event
            while (idx < configs.size() and configs[idx] != event)
                ++idx;
            if (idx == configs.size())
                configs.emplace_back(event);
            auto const name = item.substr(0, eq);
            for (auto const& known : level.names) // counts are keyed by name
                if (known == name)
                    return false;
            level.names.emplace_back(name);
            level.idx.emplace_back(idx);
            s.remove_prefix(comma == std::string_view::npos ? s.size() : comma + 1);
        }
        return !level.idx.empty();
    }
};


struct Group
{
    ~Group() { close(); }

    void close()
    {
#if defined(__linux__)
        for (auto const fd : fds)
            if (fd >= 0)
                ::close(fd);
#endif
        fds.clear();
        ok = false;
    }

    // open for the current Config if not done yet, cheap once open
    bool ensure()
    {
        auto& config = Config::INSTANCE();
        auto const g = config.generation.load(std::memory_order_relaxed);
        if (g != generation)
        {
            close();
            generation = g;
            if (config.ok or opening)
                ok = open(config);
        }
        return ok;
    }

    // all group values into out, false if the group stopped counting
    bool read(Counts& out)
    {
#if defined(__linux__)
        // PERF_FORMAT_GROUP | TOTAL_TIME_ENABLED | TOTAL_TIME_RUNNING
        std::array<std::uint64_t, 3 + max_events> buf{};
        auto const want = static_cast<ssize_t>((3 + fds.size()) * sizeof(std::uint64_t));
        auto const got  = ok ? ::read(fds[0], buf.data(), want) : ssize_t{-1};
        if (ok) // io scopes subtract these, the kernel counts them as the thread's reads
        {
            ++read_calls;
            read_bytes += got > 0 ? static_cast<std::uint64_t>(got) : 0;
        }
        if (got != want or buf[1] != buf[2])
        {
            // a pinned group that lost its counters reads 0 bytes, never scaled
            ++Config::INSTANCE().read_failures;
            return false;
        }
        for (std::size_t i = 0; i < fds.size(); ++i)
            out[i] = buf[3 + i];
        return true;
#else
        (void)out;
        return false;
#endif
    }

    std::vector<int> fds;
    std::uint64_t read_calls = 0, read_bytes = 0; // read() syscalls made, bytes returned
    std::uint64_t generation = 0;
    bool ok                  = false;
    bool opening             = false; // Config::init checking the first group
    std::string error;

private:
    bool fail(std::string const& why)
    {
        error = why;
        close();
        ++Config::INSTANCE().open_failures;
        if (!opening) // Config::init reports its own, with ", counters disabled"
            Config::INSTANCE().report("a thread could not open counters: " + why);
        return false;
    }

    bool open(Config const& config)
    {
#if defined(__linux__)
        auto const& configs = config.configs;
        if (configs.empty())
            return false;
        if (configs.size() > max_events)
            return fail(std::to_string(configs.size()) + " events, max "
                        + std::to_string(max_events));
        for (std::size_t i = 0; i < configs.size(); ++i)
        {
            perf_event_attr attr{};
            attr.size           = sizeof(attr);
            attr.type           = configs[i].type;
            attr.config         = configs[i].config;
            attr.exclude_kernel = !configs[i].kernel;
            attr.exclude_hv     = 1;
            attr.read_format    = PERF_FORMAT_GROUP | PERF_FORMAT_TOTAL_TIME_ENABLED
                               | PERF_FORMAT_TOTAL_TIME_RUNNING;
            attr.disabled    = i == 0; // leader starts the group
            attr.pinned      = i == 0;
            int const leader = i == 0 ? -1 : fds[0];
            auto const fd
                = static_cast<int>(::syscall(SYS_perf_event_open, &attr, 0, -1, leader, 0));
            if (fd < 0)
            {
                char hex[32];
                std::snprintf(hex, sizeof(hex), "%s%s%#llx", configs[i].kernel ? "k:" : "",
                              configs[i].type == type_hardware ? "hw:" : "",
                              static_cast<unsigned long long>(configs[i].config));
                return fail(std::string{"perf_event_open config "} + hex + ": "
                            + std::strerror(errno)
                            + ((errno == EACCES or errno == EPERM) and configs[i].kernel
                                   ? " (kernel space counting: kernel.perf_event_paranoid"
                                     " > 1? or set CAP_PERFMON)"
                               : errno == EACCES or errno == EPERM
                                   ? " (kernel.perf_event_paranoid > 2?)"
                               : errno == EINVAL and i > 0
                                   ? " (does not fit the PMU with the events before it,"
                                     " use smaller sets)"
                                   : ""));
            }
            fds.emplace_back(fd);
        }
        if (::ioctl(fds[0], PERF_EVENT_IOC_ENABLE, PERF_IOC_FLAG_GROUP) < 0)
            return fail(std::string{"PERF_EVENT_IOC_ENABLE: "} + std::strerror(errno));
        ok = true;

        Counts probe{};
        if (!read(probe))
            return fail(std::to_string(configs.size())
                        + " events do not fit the PMU at once (pinned group not scheduled),"
                          " use fewer events or disable the nmi watchdog");
        return true;
#else
        (void)config;
        return fail("perf counters need linux");
#endif
    }
};


// the calling thread's group, defined next to Config::INSTANCE() for the same reason
Group& local();


inline bool Config::init()
{
    close();
    read_failures = 0;
    open_failures = 0;
    reported      = false;

    for (std::size_t l = 1; l < level_env.size(); ++l)
        if (auto const* e = std::getenv(level_env[l]); e && *e)
            if (!parse(l, e))
            {
                error = "cannot parse " + std::string{level_env[l]} + "=" + e;
                report(error + ", counters disabled");
                close();
                return false;
            }
    if (configs.empty())
        return false;
    if (auto const* e = std::getenv(ctx_env); e)
    {
        if (parse_ctx(e))
            ctx = e;
        else // the "#ctx" file line must stay one line of key=integer pairs
            std::fprintf(stderr,
                         "phlop perf counters: %s=\"%s\" ignored, want key=integer,..."
                         " as printed by python3 -m phlop.app.pfm.stat --env\n",
                         ctx_env, e);
    }

    auto& group   = local(); // check now, on the calling thread, to fail early
    group.opening = true;
    ok            = group.ensure();
    group.opening = false;
    if (!ok)
    {
        error = group.error;
        report(error + ", counters disabled");
        auto const keep = error;
        close();
        error = keep;
    }
    else
        accuracy_notices();
    return ok;
}


// once per process: counts that are potentially inaccurate, why, how to resolve
inline void Config::accuracy_notices()
{
    static std::atomic<bool> printed{false};
    bool generic = false;
    for (auto const& level : levels)
        generic = generic or level.label.starts_with("generic/");
    bool kernel       = false;
    for (auto const& event : configs)
        kernel = kernel or event.kernel;
    bool const forced = pmu_forced;
    if (!(generic or forced or kernel) or printed.exchange(true))
        return;
    if (generic)
        std::fprintf(stderr,
                     "phlop perf counters: WARNING: perf generic events, no phlop event sets"
                     " for this CPU. Counts are potentially inaccurate: the kernel maps"
                     " them per CPU (cache events especially), compare runs on the same CPU"
                     " model only. Resolve: add sets for this CPU in phlop/app/pfm/sets.py,"
                     " see python3 -m phlop.app.pfm.stat --list\n");
    if (forced)
        std::fprintf(stderr,
                     "phlop perf counters: WARNING: events encoded for a libpfm PMU forced"
                     " via LIBPFM_FORCE_PMU, not this CPU's. Counts are potentially wrong:"
                     " events may count something else or nothing. Resolve: regenerate"
                     " PHLOP_PERF_* without LIBPFM_FORCE_PMU\n");
    if (kernel)
        std::fprintf(stderr,
                     "phlop perf counters: WARNING: kernel space counted, including the"
                     " kernel side of phlop's own counter reads, ~2k instructions per scope."
                     " Counts of tiny scopes are potentially dominated by it. Resolve:"
                     " regenerate PHLOP_PERF_* without --kernel for user space only\n");
}


// end of a run: "N scope reads failed" etc, empty if all went well
inline std::string summary()
{
    auto& config = Config::INSTANCE();
    std::string s;
    if (auto const n = config.read_failures.load())
        s += std::to_string(n) + " scope reads failed, those scopes have no counts. ";
    if (auto const n = config.open_failures.load(); n and config.ok)
        s += std::to_string(n) + " threads could not open counters. ";
    return s;
}

} // namespace phlop::perf

#endif /*_PHLOP_TIMING_PERF_COUNTERS_HPP_*/
